"""Text of a typed value and CSV quoting (docs/export.md, sections 7 and 8)."""

from decimal import Decimal

from tally.fmt.pattern import format_pattern


def _group(digits: str, locale) -> str:
    sizes = locale.group_sizes
    if len(digits) < sizes[0] + locale.min_grouping:
        return digits
    groups = []
    i = 0
    while len(digits) > 0:
        size = sizes[min(i, len(sizes) - 1)]
        groups.append(digits[-size:])
        digits = digits[:-size]
        i += 1
    return locale.group.join(reversed(groups))


def value_text(value, field, locale, grouping: bool) -> str:
    t = field.type
    if t == "string":
        return value
    if t in ("int", "decimal"):
        if t == "int":
            negative = value < 0
            whole, frac = str(abs(value)), ""
        else:
            negative = value < 0 and any(c in "123456789" for c in str(value))
            text = format(abs(value), "f")
            whole, _, frac = text.partition(".")
            frac = frac.ljust(field.scale, "0")
        if locale is None:
            return ("-" if negative else "") + whole + ("." + frac if t == "decimal" else "")
        if grouping:
            whole = _group(whole, locale)
        body = whole + (locale.decimal + frac if t == "decimal" else "")
        return (locale.minus if negative else "") + body
    if t == "bool":
        if locale is None:
            return "true" if value else "false"
        return locale.true if value else locale.false
    if t == "date":
        return format_pattern(value, locale.date) if locale else value.strftime("%Y-%m-%d") if value.year >= 1000 else f"{value.year:04d}-{value.month:02d}-{value.day:02d}"
    if t == "datetime":
        if locale:
            return format_pattern(value, locale.datetime)
        return (f"{value.year:04d}-{value.month:02d}-{value.day:02d}"
                f"T{value.hour:02d}:{value.minute:02d}:{value.second:02d}Z")
    raise ValueError(t)


def quote(text: str, delimiter: str, null: str) -> str:
    needs = (delimiter in text or '"' in text or "\r" in text or "\n" in text
             or text[:1] in (" ", "\t") or text[-1:] in (" ", "\t") or text == null)
    return '"' + text.replace('"', '""') + '"' if needs else text
