"""Filter expressions of export --where (docs/export.md, section 5)."""

import re
from decimal import Decimal

from tally.errors import UsageError
from tally.store.values import parse_date, parse_datetime, typed

KEYWORDS = {"and", "or", "not", "in", "is", "null", "true", "false"}
_TOKEN = re.compile(r"""\s*(?:
    (?P<str>'(?:[^']|'')*')
  | (?P<num>-?\d+(?:\.\d+)?)
  | (?P<op>!=|<=|>=|=|<|>|~)
  | (?P<punct>[(),])
  | (?P<word>[A-Za-z_][A-Za-z0-9_.]*)
)""", re.X)


def _tokenize(text: str):
    pos = 0
    out = []
    while True:
        if not text[pos:].strip():
            return out
        m = _TOKEN.match(text, pos)
        if not m:
            raise UsageError(f"--where: unexpected text at {text[pos:].strip()[:20]!r}")
        pos = m.end()
        kind = m.lastgroup
        val = m.group(kind)
        if kind == "word" and val.lower() in KEYWORDS:
            out.append(("kw", val.lower()))
        elif kind == "str":
            out.append(("str", val[1:-1].replace("''", "'")))
        else:
            out.append((kind, val))


class _Parser:
    def __init__(self, text, schema):
        self.toks = _tokenize(text)
        self.i = 0
        self.schema = schema

    def peek(self):
        return self.toks[self.i] if self.i < len(self.toks) else (None, None)

    def take(self):
        t = self.peek()
        if t[0] is None:
            raise UsageError("--where: unexpected end of expression")
        self.i += 1
        return t

    def is_kw(self, word):
        return self.peek() == ("kw", word)

    def expect(self, kind, val):
        t = self.take()
        if t != (kind, val):
            raise UsageError(f"--where: expected {val!r}, found {t[1]!r}")

    def parse(self):
        node = self.or_expr()
        if self.peek()[0] is not None:
            raise UsageError(f"--where: unexpected {self.peek()[1]!r}")
        return node

    def or_expr(self):
        parts = [self.and_expr()]
        while self.is_kw("or"):
            self.i += 1
            parts.append(self.and_expr())
        return lambda r: any(p(r) for p in parts)

    def and_expr(self):
        parts = [self.not_expr()]
        while self.is_kw("and"):
            self.i += 1
            parts.append(self.not_expr())
        return lambda r: all(p(r) for p in parts)

    def not_expr(self):
        if self.is_kw("not"):
            self.i += 1
            inner = self.not_expr()
            return lambda r: not inner(r)
        return self.primary()

    def primary(self):
        if self.peek() == ("punct", "("):
            self.i += 1
            node = self.or_expr()
            self.expect("punct", ")")
            return node
        return self.test()

    def literal(self, field):
        kind, val = self.take()
        t = field.type
        if kind == "kw" and val in ("true", "false"):
            if t != "bool":
                raise UsageError(f"--where: {field.name} is {t}; a boolean does not suit it")
            return val == "true"
        if kind == "num":
            if t not in ("int", "decimal"):
                raise UsageError(f"--where: {field.name} is {t}; a number does not suit it")
            return Decimal(val)
        if kind == "str":
            try:
                if t == "string":
                    return val
                if t == "date":
                    return parse_date(val)
                if t == "datetime":
                    if re.fullmatch(r"\d{4}-\d{2}-\d{2}", val):
                        return parse_datetime(val + "T00:00:00Z")
                    return parse_datetime(val)
            except ValueError:
                raise UsageError(f"--where: {val!r} is not a valid {t} for {field.name}") from None
            raise UsageError(f"--where: {field.name} is {t}; a string does not suit it")
        raise UsageError(f"--where: expected a literal, found {val!r}")

    def test(self):
        kind, path = self.take()
        if kind != "word":
            raise UsageError(f"--where: expected a field path, found {path!r}")
        field = self.schema.field(path)
        nxt = self.take()
        if nxt == ("kw", "is"):
            neg = False
            if self.is_kw("not"):
                self.i += 1
                neg = True
            self.expect("kw", "null")
            return lambda r: (typed(r, field) is not None) if neg else (typed(r, field) is None)
        if nxt == ("kw", "not"):
            self.expect("kw", "in")
            return self.in_list(field, True)
        if nxt == ("kw", "in"):
            return self.in_list(field, False)
        if nxt[0] != "op":
            raise UsageError(f"--where: expected an operator after {path}, found {nxt[1]!r}")
        op = nxt[1]
        if field.type == "bool" and op not in ("=", "!="):
            raise UsageError(f"--where: {op} does not apply to bool field {path}")
        if op == "~" and field.type != "string":
            raise UsageError(f"--where: ~ needs a string field; {path} is {field.type}")
        lit = self.literal(field)

        def test(r):
            v = typed(r, field)
            if v is None:
                return False
            if op == "=":
                return v == lit
            if op == "!=":
                return v != lit
            if op == "<":
                return v < lit
            if op == "<=":
                return v <= lit
            if op == ">":
                return v > lit
            if op == ">=":
                return v >= lit
            return lit in v
        return test

    def in_list(self, field, negate):
        self.expect("punct", "(")
        lits = [self.literal(field)]
        while self.peek() == ("punct", ","):
            self.i += 1
            lits.append(self.literal(field))
        self.expect("punct", ")")

        def test(r):
            v = typed(r, field)
            if v is None:
                return False
            return (v not in lits) if negate else (v in lits)
        return test


def compile_where(text: str, schema):
    return _Parser(text, schema).parse()
