"""Sort keys of export --sort (docs/export.md, section 6)."""

from tally.errors import UsageError
from tally.store.values import typed


def parse_sort(spec: str, schema):
    keys = []
    seen = set()
    for item in spec.split(","):
        parts = [p.strip() for p in item.split(":")]
        path, mods = parts[0], parts[1:]
        if not path:
            raise UsageError(f"--sort: empty field in {item!r}")
        direction = "asc"
        placement = None
        if mods and mods[0] in ("asc", "desc"):
            direction = mods.pop(0)
        if mods and mods[0] in ("nulls-first", "nulls-last"):
            placement = mods.pop(0)
        if mods:
            raise UsageError(f"--sort: malformed key {item.strip()!r}")
        field = schema.field(path)
        if path in seen:
            raise UsageError(f"--sort: {path} is listed twice")
        seen.add(path)
        desc = direction == "desc"
        nulls_first = (placement == "nulls-first") if placement else desc
        keys.append((field, desc, nulls_first))
    return keys


def sort_records(records, keys):
    for field, desc, nulls_first in reversed(keys):
        vals = [(typed(r, field), r) for r in records]
        nulls = [r for v, r in vals if v is None]
        rest = sorted((p for p in vals if p[0] is not None), key=lambda p: p[0], reverse=desc)
        rest = [r for _, r in rest]
        records = nulls + rest if nulls_first else rest + nulls
    return records
